Replace `index.ts` with:

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const stack = pulumi.getStack();

const env = config.get("env") ?? stack;
if (env !== "dev" && env !== "prod") {
    throw new Error(`Unsupported environment "${env}"; expected "dev" or "prod".`);
}

const region = config.get("region") ?? "us-east-1";
const dbPassword = config.requireSecret("dbPassword");

const provider = new aws.Provider("aws", {
    region: region as aws.Region,
});

// S3 assets bucket
const bucket = new aws.s3.Bucket("app-bucket", {
    // Include the stack to avoid dev/prod sharing the same bucket.
    bucket: `myapp-assets-${env}-${stack}`,
    versioning: {
        enabled: true,
    },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
    tags: {
        Environment: env,
        Project: "myapp",
    },
}, { provider });

new aws.s3.BucketPublicAccessBlock("app-bucket-public-access", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
}, { provider });

// Derive the URL inside Pulumi's Output graph. Do not await an Output.
const bucketUrl: pulumi.Output<string> = bucket.bucket.apply(
    bucketName => `https://${bucketName}.s3.${region}.amazonaws.com`,
);

// RDS PostgreSQL
const db = new aws.rds.Instance("app-db", {
    instanceClass: env === "prod" ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app_user",
    password: dbPassword,

    multiAz: env === "prod",
    storageEncrypted: true,
    publiclyAccessible: false,
    deletionProtection: true,
    backupRetentionPeriod: 7,

    // A final snapshot is required when deletion protection is intentionally
    // disabled before destroying the database.
    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `myapp-${env}-final`,

    tags: {
        Environment: env,
        Project: "myapp",
    },
}, { provider });

export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

Configure each stack independently:

```bash
pulumi stack init dev
pulumi config set env dev
pulumi config set region us-east-1
pulumi config set --secret dbPassword 'replace-with-generated-password'

pulumi stack init prod
pulumi config set env prod
pulumi config set region us-east-1
pulumi config set --secret dbPassword 'replace-with-generated-password'
```

The important corrections are:

- `Output<T>` is transformed with `.apply(...)`, not `await`.
- `bucketUrl` is now an `Output<string>`, not a `Promise<string>`.
- The URL uses the bucket name rather than the bucket ARN.
- The password comes from `Config.requireSecret()` and remains secret through RDS inputs and Pulumi state.
- `pulumi.output("plain-text-password")` is removed; wrapping a literal does not make it secret.
- Existing bucket and RDS settings are hardened to satisfy the relevant encryption, public-access, backup, and deletion-protection requirements.

The supplied workspace still does not implement the EKS, IAM/OIDC, HTTPS/CloudFront, or production cross-region S3 replication portions of the broader canonical scenario.
